schema_ddl:
CREATE TABLE PRODUCT (
    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
CREATE TABLE CUSTOMER (
    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

counterexample:
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1), (2), (3);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (101, 1), (101, 2), (101, 3);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (102, 1), (102, 2), (102, 1);

